calculateSlope = (data, xKey, yKey) =&gt; {
  const sumXY = d3.sum(data, d =&gt; d[xKey] * d[yKey]);
  const sumX2 = d3.sum(data, d =&gt; d[xKey] ** 2);
  return sumX2 === 0 ? 0 : sumXY / sumX2;
};

