      d.p_DistLrg === m.p_DistLrg &&
      d.a_DistLrg === m.a_DistLrg &&
      d.veh_inc === m.veh_inc
    );

    if (!o || o.total_trips === 0) return null;

    return {
      p_DistLrg: m.p_DistLrg,
      a_DistLrg: m.a_DistLrg,
      veh_inc: m.veh_inc,
      veh_inc_clean: String(m.veh_inc).replace(/^HBW_/, ""),
      Source: m.Source,
      tmeMod: m.total_trips,
      tmeObs: o.total_trips,
      tmeErrorPct: (m.total_trips - o.total_trips) / o.total_trips
    };
  }).filter(d =&gt; d !== null);
}

// 3. FINAL FILTERING
dc_filtered_2 = dc_2.filter(d =&gt; d.Source === vSource_2)

// 4. NOTEBOOK-MATCHED METRICS
slope_through_origin = (rows) =&gt; {
  const denominator = d3.sum(rows, d =&gt; d.tmeObs * d.tmeObs);
  return denominator &gt; 0
    ? d3.sum(rows, d =&gt; d.tmeObs * d.tmeMod) / denominator
    : 0;
}

wmape = (rows) =&gt; {
  const totalObs = d3.sum(rows, d =&gt; d.tmeObs);
  return totalObs &gt; 0
    ? d3.sum(rows, d =&gt; Math.abs(d.tmeMod - d.tmeObs)) / totalObs
    : 0;
}

segment_summaries = vincs_list.map(seg =&gt; {
  const rows = dc_filtered_2.filter(d =&gt; d.veh_inc_clean === seg);
  return {
    seg,
    rows,
    slope: slope_through_origin(rows),
    wmape: wmape(rows),
    maxVal: d3.max(rows, d =&gt; Math.max(d.tmeObs, d.tmeMod)) || 1
  };
})

