  const L = await require("leaflet@1.9.4");

  const container = html`&lt;div style="height:560px; width:100%; border-radius:6px; overflow:hidden;"&gt;&lt;/div&gt;`;
  yield container;

  const map = L.map(container, {zoomControl: true});

  L.tileLayer(
    "https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png",
    {
      attribution:
        '&copy; &lt;a href="https://www.openstreetmap.org/copyright"&gt;OpenStreetMap&lt;/a&gt; contributors ' +
        '&copy; &lt;a href="https://carto.com/attributions"&gt;CARTO&lt;/a&gt;',
      subdomains: "abcd",
      maxZoom: 19,
    }
  ).addTo(map);

  // Aggregate map data across all HHSize × VehOwn combinations for selected geography
  const mapAgg = d3.rollup(
    vo_filtered_base,
    v =&gt; {
      const mod = d3.sum(v, d =&gt; d.Model_HH);
      const acs = d3.sum(v, d =&gt; d.ACS_HH);
      const hts = d3.sum(v, d =&gt; d.HTS_HH);
      return {
        Model_HH: mod, ACS_HH: acs, HTS_HH: hts,
        Pct_Error:      acs &gt; 0 ? (mod - acs) / acs : null,
        Pct_Error_HTS:  hts &gt; 0 ? (mod - hts) / hts : null,
        Pct_ACS_vs_Mod: mod &gt; 0 ? (acs - mod) / mod : null,
        Pct_HTS_vs_Mod: mod &gt; 0 ? (hts - mod) / mod : null,
        Pct_ACS_vs_HTS: hts &gt; 0 ? (acs - hts) / hts : null,
        Pct_HTS_vs_ACS: acs &gt; 0 ? (hts - acs) / acs : null,
      };
    },
    d =&gt; d.GeoName
  );

  const geo_lookup = {
    "County":          {geo: geo_counties, prop: "County"},
    "Super District":  {geo: geo_super,    prop: "DSUP_NAME"},
